// Set/get the animation FPS
float GetAnimFPS() const { return mAnimFPS; }
void SetAnimFPS(float fps) { mAnimFPS = fps; }
private:
// All textures in the animation
std::vector<SDL_Texture*> mAnimTextures;
// Current frame displayed
float mCurrFrame;
// Animation frame rate
float mAnimFPS;
};
The mAnimFPS variable allows different animated sprites to run at different frame rates. It
also allows the animation to dynamically speed up or slow down. For instance, as a character
